      "evidence": "Industry classification (e.g., NAICS 334111 – Computer and Peripheral Equipment Manufacturing) places laptops in the consumer‑electronics sector, not in raw‑commodity categories.",
      "weight": 0.25,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "No laptop model appears in any official fair‑trade certification registry.",
      "evidence": "Searches of the Fairtrade International certified‑product database, the WFTO member directory, and the Fair Trade USA product list (all accessed November 2026) return zero results for laptops or any brand of notebook computers.",
      "weight": 0.25,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Because no laptop is certified, a laptop cannot be purchased that carries an official fair‑trade label.",
      "evidence": "Certification requires inclusion on the certifier’s public registry; absence from all registries means such a product is not available for sale as ‘fair‑trade’.",
      "weight": 0.20,
      "depends_on": [3]
    }
